package com.messaging.consumer

import scala.concurrent.{Future, ExecutionContext, Promise}
import scala.collection.concurrent.TrieMap
import java.util.concurrent.atomic.{AtomicReference, AtomicInteger}
import java.security.MessageDigest
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

// Message queue consumer with role-based access control
object MessageQueueConsumer {
  implicit val ec: ExecutionContext = ExecutionContext.global

  sealed trait Role
  case object Admin extends Role
  case object Operator extends Role
  case object Reader extends Role

  case class Principal(id: String, role: Role, sessionToken: String)
  case class Message(id: String, topic: String, payload: Array[Byte], requiredRole: Role)
  case class ConsumerSession(principal: Principal, subscribedTopics: Set[String], messageCount: AtomicInteger)

  private val activeSessions = TrieMap.empty[String, ConsumerSession]
  private val pendingEscalations = TrieMap.empty[String, EscalationRequest]
  private val messageBuffer = TrieMap.empty[String, Vector[Message]]
  private val hmacSecret = "queue-integrity-key-2024".getBytes("UTF-8")

  case class EscalationRequest(
    requestId: String,
    principalId: String,
    targetRole: Role,
    approvalCount: AtomicInteger,
    requiredApprovals: Int,
    resolved: AtomicReference[Option[Boolean]]
  )

  def roleOrdinal(role: Role): Int = role match {
    case Reader => 0
    case Operator => 1
    case Admin => 2
  }

  def computeSessionHmac(principal: Principal): String = {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(hmacSecret, "HmacSHA256"))
    val data = s"${principal.id}:${principal.role}:${System.nanoTime()}"
    mac.doFinal(data.getBytes("UTF-8")).map("%02x".format(_)).mkString
  }

  def authenticate(userId: String, credential: String): Future[Option[Principal]] = Future {
    // Simulated auth - in production would verify against identity provider
    val role = if (userId.startsWith("admin_")) Admin
               else if (userId.startsWith("op_")) Operator
               else Reader
    val principal = Principal(userId, role, computeSessionHmac(Principal(userId, role, "")))
    Some(principal)
  }

  def createSession(principal: Principal): Future[ConsumerSession] = Future {
    val session = ConsumerSession(principal, Set.empty, new AtomicInteger(0))
    activeSessions.put(principal.sessionToken, session)
    session
  }

  def subscribe(sessionToken: String, topic: String): Future[Boolean] = Future {
    activeSessions.get(sessionToken) match {
      case Some(session) =>
        val updated = session.copy(subscribedTopics = session.subscribedTopics + topic)
        activeSessions.put(sessionToken, updated)
        true
      case None => false
    }
  }

  // Role escalation requires multiple approvals from existing admins
  def requestEscalation(sessionToken: String, targetRole: Role): Future[Option[String]] = Future {
    activeSessions.get(sessionToken).map { session =>
      val requestId = java.util.UUID.randomUUID().toString
      val escalation = EscalationRequest(
        requestId = requestId,
        principalId = session.principal.id,
        targetRole = targetRole,
        approvalCount = new AtomicInteger(0),
        requiredApprovals = 2,
        resolved = new AtomicReference(None)
      )
      pendingEscalations.put(requestId, escalation)
      requestId
    }
  }

  def approveEscalation(approverToken: String, requestId: String): Future[Boolean] = Future {
    val approverSession = activeSessions.get(approverToken)
    val escalation = pendingEscalations.get(requestId)

    (approverSession, escalation) match {
      case (Some(approver), Some(esc)) if approver.principal.role == Admin =>
        val newCount = esc.approvalCount.incrementAndGet()
        if (newCount >= esc.requiredApprovals) {
          esc.resolved.set(Some(true))
          applyEscalation(esc)
        }
        true
      case _ => false
    }
  }

  private def applyEscalation(esc: EscalationRequest): Unit = {
    activeSessions.foreach { case (token, session) =>
      if (session.principal.id == esc.principalId) {
        val escalatedPrincipal = session.principal.copy(role = esc.targetRole)
        val escalatedSession = session.copy(principal = escalatedPrincipal)
        activeSessions.put(token, escalatedSession)
      }
    }
  }

  // Core message consumption with authorization check
  def consumeMessage(sessionToken: String, messageId: String): Future[Option[Array[Byte]]] = Future {
    activeSessions.get(sessionToken).flatMap { session =>
      messageBuffer.values.flatten.find(_.id == messageId).flatMap { message =>
        if (isAuthorized(session, message)) {
          session.messageCount.incrementAndGet()
          Some(message.payload)
        } else {
          None
        }
      }
    }
  }

  // Authorization check - verifies role hierarchy
  private def isAuthorized(session: ConsumerSession, message: Message): Boolean = {
    val hasTopicAccess = session.subscribedTopics.contains(message.topic)
    val hasRoleAccess = checkRoleAccess(session.principal.role, message.requiredRole)
    hasTopicAccess && hasRoleAccess
  }

  // The role check: does the session's role meet the message's required role?
  private def checkRoleAccess(sessionRole: Role, requiredRole: Role): Boolean = {
    roleOrdinal(sessionRole) >= roleOrdinal(requiredRole)
  }

  // Async batch processor that handles escalation + consumption atomically
  def processBatchWithEscalation(
    sessionToken: String,
    escalationRequestId: Option[String],
    messageIds: Seq[String]
  ): Future[Seq[Option[Array[Byte]]]] = {

    val escalationFuture: Future[Unit] = escalationRequestId match {
      case Some(reqId) => Future {
        pendingEscalations.get(reqId).foreach { esc =>
          // Check if escalation was resolved while we were waiting
          if (esc.resolved.get().contains(true)) {
            applyEscalation(esc)
          }
        }
      }
      case None => Future.successful(())
    }

    // Process messages after escalation check completes
    escalationFuture.flatMap { _ =>
      Future.sequence(messageIds.map(mid => consumeMessage(sessionToken, mid)))
    }
  }

  // Self-approval exploit path: the approval check uses session role
  // which can be the ESCALATED role if timing allows
  def selfApproveEscalation(sessionToken: String, requestId: String): Future[Boolean] = Future {
    val session = activeSessions.get(sessionToken)
    val escalation = pendingEscalations.get(requestId)

    (session, escalation) match {
      case (Some(s), Some(esc)) =>
        // Checks current role from session - but session may have been
        // mutated by a concurrent applyEscalation on another thread
        val currentRole = activeSessions.get(sessionToken).map(_.principal.role).getOrElse(Reader)
        if (currentRole == Admin) {
          val newCount = esc.approvalCount.incrementAndGet()
          if (newCount >= esc.requiredApprovals) {
            esc.resolved.set(Some(true))
            applyEscalation(esc)
          }
          true
        } else {
          false
        }
      case _ => false
    }
  }

  def publishMessage(topic: String, payload: Array[Byte], requiredRole: Role): Future[String] = Future {
    val id = java.util.UUID.randomUUID().toString
    val msg = Message(id, topic, payload, requiredRole)
    messageBuffer.updateWith(topic) {
      case Some(msgs) => Some(msgs :+ msg)
      case None => Some(Vector(msg))
    }
    id
  }
}
